/// A record as a record scope of expr-env: its fields and its system attributes, as expr.rs attribute reads them ($created_by only when the record has a creator).
///
/// Specification function `record-scope`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn record_scope(
    r: &types::Record,
) -> Result<std::collections::BTreeMap<String, types::Value>, Fault> {
    let base = {
        let mut map_ = {
            let mut map_ = {
                let mut map_ = {
                    let mut map_ = r
                        .fields
                        .clone()
                        .into_iter()
                        .map(|(key_, item_)| (key_.0, item_))
                        .collect::<std::collections::BTreeMap<_, _>>();
                    map_.insert("$id".to_string(), types::Value::Ref(r.id.clone()));
                    map_
                };
                map_.insert(
                    "$version".to_string(),
                    types::Value::Int(i64::try_from(r.version).map_err(|_| Fault { op: "as" })?),
                );
                map_
            };
            map_.insert(
                "$created_at".to_string(),
                types::Value::Time(r.created_at.0),
            );
            map_
        };
        map_.insert(
            "$updated_at".to_string(),
            types::Value::Time(r.updated_at.0),
        );
        map_
    };
    Ok(match &r.created_by {
        Some(p) => {
            let mut map_ = base.clone();
            map_.insert("$created_by".to_string(), types::Value::Str(p.clone().0));
            map_
        }
        None => base.clone(),
    })
}

