/// The Rust Debug text of a Need ({need:?}).
///
/// Specification function `need-debug`.
pub fn need_debug(wanted: &types::Need) -> String {
    match wanted {
        types::Need::Record { object, id } => {
            format!(
                "Record {{ object: ObjectTypeId(\"{}\"), id: RecordId({}) }}",
                object.0, id.0
            )
        }
        types::Need::ByField {
            object,
            field,
            value,
        } => {
            format!(
                "ByField {{ object: ObjectTypeId(\"{}\"), field: FieldId(\"{}\"), value: {} }}",
                object.0,
                field.0,
                value_debug(value)
            )
        }
        types::Need::AllOf(object) => format!("AllOf(ObjectTypeId(\"{}\"))", object.0),
    }
}

/// state.rs Coverage::covers: a complete snapshot covers every need; a partial one covers the needs it loaded, and a record or field lookup of an object type it loaded whole.
///
/// Specification function `covers`.
pub fn covers(coverage: &types::Coverage, wanted: &types::Need) -> bool {
    match coverage {
        types::Coverage::Complete => true,
        types::Coverage::Partial(loaded) => {
            loaded.iter().any(|n| *n == *wanted)
                || (match wanted {
                    types::Need::Record { object, .. } => loaded
                        .iter()
                        .any(|n| *n == types::Need::AllOf(object.clone())),
                    types::Need::ByField { object, .. } => loaded
                        .iter()
                        .any(|n| *n == types::Need::AllOf(object.clone())),
                    types::Need::AllOf(_) => false,
                })
        }
    }
}

/// rules.rs insufficient: the error of a lookup the snapshot does not cover, naming the need.
///
/// Specification function `insufficient`.
pub fn insufficient(wanted: &types::Need) -> types::DomainError {
    let text = need_debug(wanted);
    types::DomainError {
        kind: types::ErrorKind::InsufficientState,
        message: format!("the snapshot does not cover {text}"),
        evidence: vec![types::Check {
            rule: "coverage".to_string(),
            passed: false,
            detail: text.clone(),
        }],
        missing: Some(wanted.clone()),
    }
}

/// rules.rs Lookup::record: the record of an object type with an id, refused when the snapshot does not cover it.
///
/// Specification function `lookup-record`; fails with `rejection`.
pub fn lookup_record(
    tenant: &types::TenantState,
    coverage: &types::Coverage,
    object: &types::ObjectTypeId,
    id: &types::RecordId,
) -> Result<Option<types::Record>, types::Rejection> {
    let wanted = types::Need::Record {
        object: object.clone(),
        id: id.clone(),
    };
    Ok((if covers(coverage, &wanted) {
        match tenant.records.get(object) {
            Some(rs) => rs.get(id).cloned(),
            None => None,
        }
    } else {
        return Err(types::Rejection::Rejected(insufficient(&wanted)));
    })
    .map(|item_| <types::Record as Clone>::clone(&item_)))
}

