    /// Example 1 of `set-of`.
    #[test]
    fn set_of_example_1() {
        let items: Vec<types::RoleId> = vec![
            types::RoleId("author".to_string()),
            types::RoleId("public".to_string()),
            types::RoleId("author".to_string()),
        ];
        let want_: std::collections::BTreeSet<types::RoleId> = std::collections::BTreeSet::from([
            types::RoleId("author".to_string()),
            types::RoleId("public".to_string()),
        ]);
        assert_eq!(set_of(&items), want_);
    }

