    /// behaviour.rs a_thin_snapshot_is_refused_with_the_missing_need: an empty partial snapshot covers nothing.
    #[test]
    fn covers_example_2() {
        let coverage: types::Coverage = types::Coverage::Partial(std::collections::BTreeSet::new());
        let wanted: types::Need = types::Need::ByField {
            object: types::ObjectTypeId("note".to_string()),
            field: types::FieldId("slug".to_string()),
            value: types::Value::Str("first".to_string()),
        };
        assert!(!covers(&coverage, &wanted));
    }

