    /// Example 3 of `policy-check-text`.
    #[test]
    fn policy_check_text_example_3() {
        let c: types::PolicyCheck = types::PolicyCheck {
            rule: "policy:public_reads_published".to_string(),
            passed: false,
            what: "Read on Object(ObjectTypeId(\"note\"))".to_string(),
            outcome: types::PolicyOutcome::IsNull,
            condition: Some(types::Expr::Cmp(
                types::CmpOp::Eq,
                Box::new(types::Expr::Var(types::Scope::Record, "status".to_string())),
                Box::new(types::Expr::Lit(types::Value::Str("published".to_string()))),
            )),
        };
        let conditions: std::collections::BTreeMap<String, String> =
            std::collections::BTreeMap::from([
                (
                    "policy:public_reads_published".to_string(),
                    "(record.status == 'published')".to_string(),
                ),
                (
                    "policy:writers_edit_own".to_string(),
                    "(record.$created_by == principal)".to_string(),
                ),
            ]);
        let want_: types::Check = types::Check {
            rule: "policy:public_reads_published".to_string(),
            passed: false,
            detail: "(record.status == 'published') is null".to_string(),
        };
        assert_eq!(policy_check_text(&c, &conditions), want_);
    }

    /// Example 4 of `policy-check-text`.
    #[test]
    fn policy_check_text_example_4() {
        let c: types::PolicyCheck = types::PolicyCheck {
            rule: "policy:none".to_string(),
            passed: false,
            what: "Manage on Members".to_string(),
            outcome: types::PolicyOutcome::NoPolicy,
            condition: None,
        };
        let conditions: std::collections::BTreeMap<String, String> =
            std::collections::BTreeMap::new();
        let want_: types::Check = types::Check {
            rule: "policy:none".to_string(),
            passed: false,
            detail: "no policy grants Manage on Members".to_string(),
        };
        assert_eq!(policy_check_text(&c, &conditions), want_);
    }

    /// Example 5 of `policy-check-text`.
