    /// Example 1 of `api-error-of`.
    #[test]
    fn api_error_of_example_1() {
        let error: types::DomainError = types::DomainError {
            kind: types::ErrorKind::Unauthorized,
            message: "Anonymous may not Create Object(ObjectTypeId(\"post\"))".to_string(),
            evidence: vec![types::Check {
                rule: "policy:none".to_string(),
                passed: false,
                detail: "no policy grants Create on Object(ObjectTypeId(\"post\"))".to_string(),
            }],
            missing: None,
        };
        let context: types::Context = types::Context {
            tenant: types::TenantId("alpha".to_string()),
            principal: types::Principal::Anonymous,
            session: None,
            now: crate::prelude::Timestamp(3000),
            correlation: "c-1".to_string(),
            verified_address: None,
        };
        let want_: types::ApiError = types::ApiError {
            code: types::ErrorCode::Unauthenticated,
            message: "Anonymous may not Create Object(ObjectTypeId(\"post\"))".to_string(),
            kind: Some("Unauthorized".to_string()),
            failed: Some(vec![types::Check {
                rule: "policy:none".to_string(),
                passed: false,
                detail: "no policy grants Create on Object(ObjectTypeId(\"post\"))".to_string(),
            }]),
            correlation: "c-1".to_string(),
        };
        assert_eq!(api_error_of(&error, &context), want_);
    }

    /// Example 2 of `api-error-of`.
    #[test]
    fn api_error_of_example_2() {
        let error: types::DomainError = types::DomainError {
            kind: types::ErrorKind::VersionConflict,
            message: "record is at version 2, expected 1".to_string(),
            evidence: vec![
                types::Check {
                    rule: "policy:builtin_owner".to_string(),
                    passed: true,
                    detail: "Update on Object(ObjectTypeId(\"post\"))".to_string(),
                },
                types::Check {
                    rule: "record:version".to_string(),
                    passed: false,
                    detail: "record is at version 2, expected 1".to_string(),
                },
            ],
            missing: None,
        };
        let context: types::Context = types::Context {
            tenant: types::TenantId("alpha".to_string()),
            principal: types::Principal::User(types::PrincipalId("alpha:owner".to_string())),
            session: Some(types::SessionId("s-1".to_string())),
            now: crate::prelude::Timestamp(3000),
            correlation: "c-1".to_string(),
            verified_address: None,
        };
        let want_: types::ApiError = types::ApiError {
            code: types::ErrorCode::Conflict,
            message: "record is at version 2, expected 1".to_string(),
            kind: Some("VersionConflict".to_string()),
            failed: Some(vec![types::Check {
                rule: "record:version".to_string(),
                passed: false,
                detail: "record is at version 2, expected 1".to_string(),
            }]),
            correlation: "c-1".to_string(),
        };
        assert_eq!(api_error_of(&error, &context), want_);
    }

