    /// behaviour.rs only_the_system_creates_tenants_and_a_tenant_is_created_once.
    #[test]
    fn kernel_transition_example_1() {
        let state: types::State = types::State {
            tenant_id: types::TenantId("gamma".to_string()),
            tenant: None,
            coverage: types::Coverage::Complete,
        };
        let intent: types::Intent = types::Intent::CreateTenant {
            name: "Gamma".to_string(),
            owner: types::PrincipalId("gamma:owner".to_string()),
        };
        let context: types::Context = types::Context {
            tenant: types::TenantId("gamma".to_string()),
            principal: types::Principal::System,
            session: None,
            now: crate::prelude::Timestamp(5001),
            correlation: "test-5001".to_string(),
            verified_address: None,
        };
        let texts: types::IntentTexts = types::IntentTexts {
            defaults: std::collections::BTreeMap::new(),
            constraints: std::collections::BTreeMap::new(),
            conditions: std::collections::BTreeMap::new(),
            blank_name: false,
        };
        let want_: types::TransitionResult = types::TransitionResult {
            delta: types::StateDelta {
                tenant: types::TenantId("gamma".to_string()),
                base_revision: None,
                new_revision: types::StateRevision(1),
                next_record: 1,
                event_seq: 1,
                ops: vec![
                    types::DeltaOp::CreateTenant {
                        name: "Gamma".to_string(),
                    },
                    types::DeltaOp::PutSchema(std::sync::Arc::new(types::TenantSchema {
                        version: types::SchemaVersion(1),
                        objects: std::collections::BTreeMap::new(),
                        roles: std::collections::BTreeMap::from([
                            (
                                types::RoleId("owner".to_string()),
                                types::RoleDef {
                                    id: types::RoleId("owner".to_string()),
                                    label: "Owner".to_string(),
                                },
                            ),
                            (
                                types::RoleId("public".to_string()),
                                types::RoleDef {
                                    id: types::RoleId("public".to_string()),
                                    label: "Everyone".to_string(),
                                },
                            ),
                        ]),
                        role_permissions: None,
                        teams: None,
                        invitations: None,
                        policies: std::collections::BTreeMap::new(),
                        workflows: std::collections::BTreeMap::new(),
                        queries: std::collections::BTreeMap::new(),
                        views: std::collections::BTreeMap::new(),
                    })),
                    types::DeltaOp::PutMember {
                        principal: types::PrincipalId("gamma:owner".to_string()),
                        roles: std::collections::BTreeSet::from([types::RoleId(
                            "owner".to_string(),
                        )]),
                    },
                ],
            },
            events: vec![types::DomainEvent {
                tenant: types::TenantId("gamma".to_string()),
                seq: 1,
                revision: types::StateRevision(1),
                at: crate::prelude::Timestamp(5001),
                principal: types::Principal::System,
                correlation: "test-5001".to_string(),
                body: types::EventBody::TenantCreated {
                    name: "Gamma".to_string(),
                },
            }],
            effects: vec![types::Effect::Publish { seq: 1 }],
            evidence: vec![types::Check {
                rule: "policy:builtin_system".to_string(),
                passed: true,
                detail: "CreateTenant".to_string(),
            }],
            output: types::Output::Tenant,
        };
        assert_eq!(
            kernel_transition(&state, &intent, &context, &texts),
            Ok(want_)
        );
    }

    /// Example 2 of `kernel-transition`.
    #[test]
    fn kernel_transition_example_2() {
        let state: types::State = types::State {
            tenant_id: types::TenantId("gamma".to_string()),
            tenant: None,
            coverage: types::Coverage::Complete,
        };
        let intent: types::Intent = types::Intent::CreateTenant {
            name: "Gamma".to_string(),
            owner: types::PrincipalId("gamma:owner".to_string()),
        };
        let context: types::Context = types::Context {
            tenant: types::TenantId("alpha".to_string()),
            principal: types::Principal::System,
            session: None,
            now: crate::prelude::Timestamp(5001),
            correlation: "test-5001".to_string(),
            verified_address: None,
        };
        let texts: types::IntentTexts = types::IntentTexts {
            defaults: std::collections::BTreeMap::new(),
            constraints: std::collections::BTreeMap::new(),
            conditions: std::collections::BTreeMap::new(),
            blank_name: false,
        };
        assert_eq!(
            kernel_transition(&state, &intent, &context, &texts),
            Err(Failure::Error(types::Rejection::Rejected(
                types::DomainError {
                    kind: types::ErrorKind::TenantMismatch,
                    message: "snapshot is of gamma, context names alpha".to_string(),
                    evidence: vec![types::Check {
                        rule: "tenant:snapshot_matches_context".to_string(),
                        passed: false,
                        detail: "snapshot is of gamma, context names alpha".to_string()
                    }],
                    missing: None
                }
            )))
        );
    }

