    /// A member of a team holds its roles beside its own.
    #[test]
    fn assigned_roles_example_1() {
        let members: std::collections::BTreeMap<
            types::PrincipalId,
            std::collections::BTreeSet<types::RoleId>,
        > = std::collections::BTreeMap::from([(
            types::PrincipalId("alpha:guest".to_string()),
            std::collections::BTreeSet::from([types::RoleId("writer".to_string())]),
        )]);
        let schema: types::TenantSchema = types::TenantSchema {
            version: types::SchemaVersion(2),
            objects: std::collections::BTreeMap::new(),
            roles: std::collections::BTreeMap::from([
                (
                    types::RoleId("editor".to_string()),
                    types::RoleDef {
                        id: types::RoleId("editor".to_string()),
                        label: "Editor".to_string(),
                    },
                ),
                (
                    types::RoleId("owner".to_string()),
                    types::RoleDef {
                        id: types::RoleId("owner".to_string()),
                        label: "Owner".to_string(),
                    },
                ),
                (
                    types::RoleId("public".to_string()),
                    types::RoleDef {
                        id: types::RoleId("public".to_string()),
                        label: "Everyone".to_string(),
                    },
                ),
                (
                    types::RoleId("writer".to_string()),
                    types::RoleDef {
                        id: types::RoleId("writer".to_string()),
                        label: "Writer".to_string(),
                    },
                ),
            ]),
            role_permissions: None,
            teams: Some(std::collections::BTreeMap::from([(
                types::TeamId("desk".to_string()),
                types::TeamDef {
                    id: types::TeamId("desk".to_string()),
                    label: "Desk".to_string(),
                    members: std::collections::BTreeSet::from([types::PrincipalId(
                        "alpha:guest".to_string(),
                    )]),
                    roles: std::collections::BTreeSet::from([types::RoleId("editor".to_string())]),
                },
            )])),
            invitations: None,
            policies: std::collections::BTreeMap::new(),
            workflows: std::collections::BTreeMap::new(),
            queries: std::collections::BTreeMap::new(),
            views: std::collections::BTreeMap::new(),
        };
        let id: types::PrincipalId = types::PrincipalId("alpha:guest".to_string());
        let want_: std::collections::BTreeSet<types::RoleId> = std::collections::BTreeSet::from([
            types::RoleId("editor".to_string()),
            types::RoleId("writer".to_string()),
        ]);
        assert_eq!(assigned_roles(&members, &schema, &id), want_);
    }

