    /// Example 1 of `role-permissions-with`.
    #[test]
    fn role_permissions_with_example_1() {
        let schema: types::TenantSchema = types::TenantSchema {
            version: types::SchemaVersion(2),
            objects: std::collections::BTreeMap::new(),
            roles: std::collections::BTreeMap::from([
                (
                    types::RoleId("editor".to_string()),
                    types::RoleDef {
                        id: types::RoleId("editor".to_string()),
                        label: "Editor".to_string(),
                    },
                ),
                (
                    types::RoleId("owner".to_string()),
                    types::RoleDef {
                        id: types::RoleId("owner".to_string()),
                        label: "Owner".to_string(),
                    },
                ),
                (
                    types::RoleId("public".to_string()),
                    types::RoleDef {
                        id: types::RoleId("public".to_string()),
                        label: "Everyone".to_string(),
                    },
                ),
                (
                    types::RoleId("writer".to_string()),
                    types::RoleDef {
                        id: types::RoleId("writer".to_string()),
                        label: "Writer".to_string(),
                    },
                ),
            ]),
            role_permissions: None,
            teams: None,
            invitations: None,
            policies: std::collections::BTreeMap::new(),
            workflows: std::collections::BTreeMap::new(),
            queries: std::collections::BTreeMap::new(),
            views: std::collections::BTreeMap::new(),
        };
        let role: types::RoleId = types::RoleId("editor".to_string());
        let permissions: Vec<types::Permission> = vec![
            types::Permission::Object {
                object: types::ObjectTypeId("note".to_string()),
                actions: std::collections::BTreeSet::from([
                    types::ObjectAction::Read,
                    types::ObjectAction::Update,
                ]),
            },
            types::Permission::Capability("content-write".to_string()),
        ];
        let want_: Option<std::collections::BTreeMap<types::RoleId, Vec<types::Permission>>> =
            Some(std::collections::BTreeMap::from([(
                types::RoleId("editor".to_string()),
                vec![
                    types::Permission::Object {
                        object: types::ObjectTypeId("note".to_string()),
                        actions: std::collections::BTreeSet::from([
                            types::ObjectAction::Read,
                            types::ObjectAction::Update,
                        ]),
                    },
                    types::Permission::Capability("content-write".to_string()),
                ],
            )]));
        assert_eq!(role_permissions_with(&schema, &role, &permissions), want_);
    }

